insert into public.menu_items (id, parent_id, label, target, sort, visible) values ('bbecc401-d16f-5f42-9381-004e73f824db', null, '{"en": "Contact", "ml": "ബന്ധപ്പെടുക"}'::jsonb, '#contact', 100, true);
insert into public.sections (id, slug, kind, eyebrow, title, body, image_url, image_caption, cta_label, cta_link, settings, sort, visible) values ('4cffd96b-7abf-5855-81d1-f46d6dcf22d8', 'home', 'hero', '{"en": "St. Mary’s Sui Juris Priory · Mariamala", "ml": "സെന്റ് മേരീസ് പ്രയറി · മരിയമല"}'::jsonb, '{"en": "Ora et labora: a life of prayer and work", "ml": "Ora et labora: പ്രാർത്ഥനയുടെയും അധ്വാനത്തിന്റെയും ജീവിതം"}'::jsonb, '{"en": "<p>The Vallombrosan Benedictine Congregation belongs to the worldwide Benedictine Confederation and follows the Rule of St. Benedict. In India its monks live in the Oriental tradition of the Syro-Malabar Church.</p>", "ml": ""}'::jsonb, 'assets/img/client/mariamala-front.1379.jpg#w=800,1200,1379&f=50,62,1', '{"en": "St. Mary’s Monastery, Mariamala, Kaduthuruthy", "ml": "സെന്റ് മേരീസ് ആശ്രമം, മരിയമല, കടുത്തുരുത്തി"}'::jsonb, '{"en": "Visit the monastery", "ml": "ആശ്രമം സന്ദർശിക്കുക"}'::jsonb, '#contact', '{"show_now": true}'::jsonb, 10, true);
insert into public.sections (id, slug, kind, eyebrow, title, body, image_url, image_caption, cta_label, cta_link, settings, sort, visible) values ('4d2983ab-2393-5fa5-9994-5a54a7cd2ff0', 'highlights', 'tiles', '{"en": "", "ml": ""}'::jsonb, '{"en": "", "ml": ""}'::jsonb, '{"en": "", "ml": ""}'::jsonb, null, '{"en": "", "ml": ""}'::jsonb, '{"en": "", "ml": ""}'::jsonb, null, '{}'::jsonb, 20, true);
insert into public.sections (id, slug, kind, eyebrow, title, body, image_url, image_caption, cta_label, cta_link, settings, sort, visible) values ('cd69d3c2-ae49-5692-a280-53eb931aa643', 'heritage', 'story', '{"en": "Origin", "ml": "ഉത്ഭവം"}'::jsonb, '{"en": "St. John Gualbert and Vallombrosa", "ml": "വിശുദ്ധ ജോൺ ഗ്വാൽബെർട്ടും വല്ലോംബ്രോസയും"}'::jsonb, '{"en": "<p>The Vallombrosan Benedictine Congregation is a member of the worldwide Benedictine Confederation and follows the Rule of St. Benedict, the father of Western monasticism. Its guiding motto is <i>Ora et labora</i>, prayer and work.</p><p>The congregation was founded by St. John Gualbert in 1036 at Vallombrosa, near Florence. After his brother was murdered, John set out to take revenge. On Good Friday he came upon the murderer and was about to kill him, but the man begged for mercy in the name of Christ crucified. John forgave him, and that forgiveness awoke in him a deep love for the crucified Christ. He went to pray in the church of San Miniato in Florence, where, the tradition says, the crucifix bowed its head to him.</p><blockquote>From an act of forgiveness came a life given entirely to God.</blockquote><p>After years of prayer and reflection he founded the Vallombrosan congregation, giving first place to community life rooted in charity. By the time of his death there were nearly twelve monasteries across Italy.</p><p>By the founder’s will, the congregation exists for the <i>vinculum caritatis et consuetudinis</i>, the bond of charity and common life between its communities, which under the authority of the Abbot General help one another to safeguard and foster the consecrated life of their monks.</p>", "ml": ""}'::jsonb, 'assets/img/vallombrosa-nave.334.jpg#w=334', '{"en": "The abbey church at Vallombrosa, near Florence", "ml": "ഫ്ലോറൻസിനടുത്തുള്ള വല്ലോംബ്രോസ ആബി ദേവാലയം"}'::jsonb, '{"en": "", "ml": ""}'::jsonb, null, '{"layout": "image", "photo_position": "beside"}'::jsonb, 30, true);
insert into public.sections (id, slug, kind, eyebrow, title, body, image_url, image_caption, cta_label, cta_link, settings, sort, visible) values ('b80382fb-e6ef-51d2-8512-a2f50c226679', 'india', 'story', '{"en": "In the Archdiocese of Kottayam", "ml": "കോട്ടയം അതിരൂപതയിൽ"}'::jsonb, '{"en": "The Vallombrosan community in India", "ml": "ഭാരതത്തിലെ വല്ലോംബ്രോസൻ സമൂഹം"}'::jsonb, '{"en": "<p>In 1988, at the request of the then Abbot General, Dom Antonio Lorenzo Russo OSB, the Priory of Our Lady of Montenero in Livorno founded a seminary in the Diocese of Kottayam, Kerala, with the approval of Mar Kuriakose Kunnassery, Bishop of Kottayam. The community was founded in the Oriental tradition of the Syro-Malabar Major Archiepiscopal Church, with the authorisation of the Congregation for the Oriental Churches in Rome.</p><p>Formation began at the Carlos Dayara minor seminary at S.H. Mount, Kottayam, at first under priests of the Kottayam diocese appointed by Mar Kuriakose Kunnassery. The Priory of Montenero guided the formation of the candidates and the early growth of the Indian foundation. The first candidates completed their formation in India and then went to Italy, where they made their monastic profession.</p><p>Mar Mathew Moolakkattu, a diocesan priest of Kottayam, joined the congregation, completed his novitiate and made his monastic profession. Shortly after his solemn profession, on 6 January 1996, Pope Saint John Paul II appointed him Auxiliary Bishop of Kottayam. Today he is the Metropolitan Archbishop of Kottayam.</p>", "ml": ""}'::jsonb, 'assets/img/client/mariamala-monks.1379.jpg#w=800,1200,1379&f=50,65,1', '{"en": "Monks of Mariamala", "ml": ""}'::jsonb, '{"en": "", "ml": ""}'::jsonb, null, '{"layout": "image"}'::jsonb, 40, true);
insert into public.sections (id, slug, kind, eyebrow, title, body, image_url, image_caption, cta_label, cta_link, settings, sort, visible) values ('cb123cf5-b1df-5ff4-8f75-0f934d2f0564', 'today', 'stats', '{"en": "The community today", "ml": "സമൂഹം ഇന്ന്"}'::jsonb, '{"en": "", "ml": ""}'::jsonb, '{"en": "", "ml": ""}'::jsonb, null, '{"en": "", "ml": ""}'::jsonb, '{"en": "", "ml": ""}'::jsonb, null, '{}'::jsonb, 50, true);
insert into public.sections (id, slug, kind, eyebrow, title, body, image_url, image_caption, cta_label, cta_link, settings, sort, visible) values ('7495e89e-aea7-5058-b434-93a1406b0100', 'mariamala', 'story', '{"en": "St. Mary’s Monastery", "ml": "സെന്റ് മേരീസ് ആശ്രമം"}'::jsonb, '{"en": "Mariamala, Kaduthuruthy", "ml": "മരിയമല, കടുത്തുരുത്തി"}'::jsonb, '{"en": "<p>The hope of a traditional Benedictine monastery was there from the first years of the Indian community. Mar Kuriakose Kunnassery, then Metropolitan Archbishop, chose a beautiful hill at Kaduthuruthy for it and named the place Mariamala. After many years of waiting, the monastery was blessed on 29 June 2012.</p><p>In June 2016 St. Mary’s Monastery, Mariamala, was made an independent priory (sui juris priory). It is the headquarters of the Vallombrosan Benedictine Congregation in India, a meeting of Western monasticism and Eastern spirituality, and a spiritual centre for the Archeparchy of Kottayam and the Syro-Malabar Church.</p><p>Its monastic chapel holds the monastic choir, a distinctive part of the Benedictine tradition, built in harmony with the architecture of the Syro-Malabar Church.</p>", "ml": ""}'::jsonb, 'assets/img/client/mariamala-chapel.1379.jpg#w=800,1200,1379&f=50,40,1', '{"en": "The monastic chapel, Mariamala", "ml": ""}'::jsonb, '{"en": "", "ml": ""}'::jsonb, null, '{"layout": "image"}'::jsonb, 60, true);
insert into public.sections (id, slug, kind, eyebrow, title, body, image_url, image_caption, cta_label, cta_link, settings, sort, visible) values ('cf7e298c-c92e-5bda-bbbd-343d07df7d00', 'leadership', 'cards', '{"en": "Leadership", "ml": "നേതൃത്വം"}'::jsonb, '{"en": "Shepherds of the community", "ml": "സമൂഹത്തിന്റെ ഇടയന്മാർ"}'::jsonb, '{"en": "", "ml": ""}'::jsonb, null, '{"en": "", "ml": ""}'::jsonb, '{"en": "", "ml": ""}'::jsonb, null, '{"photo": "portrait"}'::jsonb, 70, true);
insert into public.sections (id, slug, kind, eyebrow, title, body, image_url, image_caption, cta_label, cta_link, settings, sort, visible) values ('606f0ad1-1af2-592e-80e5-17da52a62b10', 'houses', 'cards', '{"en": "Monasteries and houses", "ml": "ആശ്രമങ്ങളും ഭവനങ്ങളും"}'::jsonb, '{"en": "Our houses in India", "ml": "ഭാരതത്തിലെ ഞങ്ങളുടെ ഭവനങ്ങൾ"}'::jsonb, '{"en": "", "ml": ""}'::jsonb, null, '{"en": "", "ml": ""}'::jsonb, '{"en": "", "ml": ""}'::jsonb, null, '{}'::jsonb, 80, true);
insert into public.sections (id, slug, kind, eyebrow, title, body, image_url, image_caption, cta_label, cta_link, settings, sort, visible) values ('07248209-281f-56b8-bd11-7a758be83584', 'community', 'cards', '{"en": "The monks", "ml": "സന്യാസികൾ"}'::jsonb, '{"en": "Our community", "ml": "ഞങ്ങളുടെ സമൂഹം"}'::jsonb, '{"en": "", "ml": ""}'::jsonb, null, '{"en": "", "ml": ""}'::jsonb, '{"en": "", "ml": ""}'::jsonb, null, '{}'::jsonb, 90, true);
insert into public.sections (id, slug, kind, eyebrow, title, body, image_url, image_caption, cta_label, cta_link, settings, sort, visible) values ('a7958de7-5621-57c7-b89f-41684272e961', 'italy', 'cards', '{"en": "The wider congregation", "ml": "സന്യാസസമൂഹം ലോകമെങ്ങും"}'::jsonb, '{"en": "Our monasteries in Italy", "ml": "ഇറ്റലിയിലെ ആശ്രമങ്ങൾ"}'::jsonb, '{"en": "", "ml": ""}'::jsonb, null, '{"en": "", "ml": ""}'::jsonb, '{"en": "", "ml": ""}'::jsonb, null, '{}'::jsonb, 100, true);
insert into public.sections (id, slug, kind, eyebrow, title, body, image_url, image_caption, cta_label, cta_link, settings, sort, visible) values ('16f0ec4e-290d-5d18-81de-81add0f9af5b', 'spirituality', 'story', '{"en": "Spirituality", "ml": "ആധ്യാത്മികത"}'::jsonb, '{"en": "A life centred on prayer", "ml": "പ്രാർത്ഥന കേന്ദ്രമാക്കിയ ജീവിതം"}'::jsonb, '{"en": "<p>The Vallombrosan Benedictines are a contemplative order whose monks centre their lives on prayer. Each monk is sustained by the daily celebration of the Eucharist and the Divine Office, and the meditative praying of the Office is the heart of a monk’s life.</p><p>Monks live this life of prayer in a community that fosters the joy of brotherhood, and each monastery is a living witness to the self-giving love of Jesus Christ. The quiet of a Benedictine monastery opens into meditation and prayer.</p><p>The monks also take part in manual work, education and pastoral service. Bringing prayer and work together is at the heart of Vallombrosan spirituality.</p>", "ml": ""}'::jsonb, 'assets/img/client/mariamala-chapel-students.1379.jpg#w=800,1200,1379&f=50,55,1', '{"en": "Prayer in the chapel at Mariamala", "ml": ""}'::jsonb, '{"en": "", "ml": ""}'::jsonb, null, '{"layout": "image"}'::jsonb, 110, true);
insert into public.sections (id, slug, kind, eyebrow, title, body, image_url, image_caption, cta_label, cta_link, settings, sort, visible) values ('8e8120af-65f9-5c90-adda-01339a20a781', 'horarium', 'horarium', '{"en": "Ora et labora", "ml": "Ora et labora"}'::jsonb, '{"en": "The monastic day", "ml": "സന്യാസ ദിനം"}'::jsonb, '{"en": "<p>All times are Indian Standard Time.</p>", "ml": "<p>എല്ലാ സമയങ്ങളും ഇന്ത്യൻ സ്റ്റാൻഡേർഡ് സമയം.</p>"}'::jsonb, null, '{"en": "", "ml": ""}'::jsonb, '{"en": "", "ml": ""}'::jsonb, null, '{}'::jsonb, 120, true);
insert into public.sections (id, slug, kind, eyebrow, title, body, image_url, image_caption, cta_label, cta_link, settings, sort, visible) values ('3331da9a-4dcf-5e9a-9f03-65e230ccb5e1', 'formation', 'steps', '{"en": "Vocations", "ml": "ദൈവവിളി"}'::jsonb, '{"en": "The path of monastic formation", "ml": "സന്യാസ പരിശീലനത്തിന്റെ വഴി"}'::jsonb, '{"en": "<p>Young men who feel called to the monastic and priestly life are welcomed at Carlos Dayara and accompanied step by step.</p>", "ml": "<p>സന്യാസ-പൗരോഹിത്യ ജീവിതത്തിലേക്ക് വിളി അനുഭവിക്കുന്ന യുവാക്കളെ കാർലോസ് ദയറയിൽ സ്വാഗതം ചെയ്യുകയും ഓരോ ഘട്ടത്തിലും അനുധാവനം ചെയ്യുകയും ചെയ്യുന്നു.</p>"}'::jsonb, null, '{"en": "", "ml": ""}'::jsonb, '{"en": "Enquire about a vocation", "ml": "ദൈവവിളിയെക്കുറിച്ച് അന്വേഷിക്കുക"}'::jsonb, '#contact', '{}'::jsonb, 130, true);
insert into public.sections (id, slug, kind, eyebrow, title, body, image_url, image_caption, cta_label, cta_link, settings, sort, visible) values ('99f37fdc-20d0-525b-9a0a-019f656df756', 'ministries', 'cards', '{"en": "School ministry", "ml": "വിദ്യാഭ്യാസ ശുശ്രൂഷ"}'::jsonb, '{"en": "Schools and education", "ml": "സ്കൂളുകളും വിദ്യാഭ്യാസവും"}'::jsonb, '{"en": "<p>In Europe, Benedictine monasteries were centres of learning and culture. Continuing that tradition, the Vallombrosan Benedictines in Kerala run schools and an institute.</p>", "ml": ""}'::jsonb, null, '{"en": "", "ml": ""}'::jsonb, '{"en": "", "ml": ""}'::jsonb, null, '{}'::jsonb, 140, true);
insert into public.sections (id, slug, kind, eyebrow, title, body, image_url, image_caption, cta_label, cta_link, settings, sort, visible) values ('b9d9f2af-5a7e-5812-9fe3-5d1b94100120', 'pastoral', 'story', '{"en": "Pastoral activities", "ml": "അജപാലന പ്രവർത്തനങ്ങൾ"}'::jsonb, '{"en": "Serving the faithful", "ml": "വിശ്വാസികളുടെ ശുശ്രൂഷയിൽ"}'::jsonb, '{"en": "<p>Benedictine monasteries are places of spiritual comfort and contemplation. The priest-monks of Mariamala are always ready to meet the spiritual needs of the faithful around them.</p><p>They serve in the Archdiocese of Kottayam and in other dioceses in India and abroad. The congregation’s monasteries include sanctuaries and basilicas where the monks hear confessions and lead devotions, and some monks serve in parishes.</p>", "ml": ""}'::jsonb, 'assets/img/client/hosur-2.1380.jpg#w=800,1200,1380&f=50,80,1', '{"en": "St. Benedict Ashram, Hosur", "ml": ""}'::jsonb, '{"en": "", "ml": ""}'::jsonb, null, '{"layout": "image"}'::jsonb, 150, true);
