insert into public.section_items (id, section_id, label, title, body, image_url, link, extra, sort, visible) values ('2c9e34fc-094d-5f1e-8748-1c4999032c7b', 'cf7e298c-c92e-5bda-bbbd-343d07df7d00', '{"en": "Metropolitan Archbishop of Kottayam", "ml": ""}'::jsonb, '{"en": "Mar Mathew Moolakkattu OSB", "ml": ""}'::jsonb, '{"en": "<p>A monk of the Vallombrosan Congregation</p>", "ml": ""}'::jsonb, 'assets/img/client/archbishop.366.jpg#w=366', null, '{}'::jsonb, 30, true);
insert into public.section_items (id, section_id, label, title, body, image_url, link, extra, sort, visible) values ('f3fb89f4-c569-557f-be13-cb1a9b37591d', '606f0ad1-1af2-592e-80e5-17da52a62b10', '{"en": "Sui juris priory", "ml": ""}'::jsonb, '{"en": "St. Mary’s Monastery, Mariamala", "ml": ""}'::jsonb, '{"en": "<p>Headquarters of the congregation in India, with its monastic chapel and choir.</p><p>Thiruvampady P.O., SKPS Road, Kaduthuruthy, Kottayam 686612</p>", "ml": ""}'::jsonb, 'assets/img/client/mariamala-front-wide.1384.jpg#w=800,1200,1384', null, '{}'::jsonb, 10, true);
insert into public.section_items (id, section_id, label, title, body, image_url, link, extra, sort, visible) values ('77001c10-0bba-57ab-b1b0-8481651521f6', '606f0ad1-1af2-592e-80e5-17da52a62b10', '{"en": "Dependent monastery", "ml": ""}'::jsonb, '{"en": "Gualbert Bhavan, Bengaluru", "ml": ""}'::jsonb, '{"en": "<p>Founded in 1999 and inaugurated on 18 June 2000 for the philosophical and theological training of candidates. Fr. Michael Kannala OSB, the first Indian monk to be professed, started the “Vallombrosa” Italian cheese factory here, whose cheeses are served in well-known restaurants across India, a living example of Benedictine manual labour. The house also offers residence to priests studying in Bengaluru and to students of Don Bosco College, T.C. Palaya.</p><p>T.C. Palaya P.O., K.R. Puram, Bengaluru 560036</p>", "ml": ""}'::jsonb, 'assets/img/client/gualbert-bhavan-1.1600.jpg#w=800,1200,1600', null, '{}'::jsonb, 20, true);
insert into public.section_items (id, section_id, label, title, body, image_url, link, extra, sort, visible) values ('cbb0a89e-676f-5ef4-a534-e78fde3f22f2', '606f0ad1-1af2-592e-80e5-17da52a62b10', '{"en": "Dependent monastery", "ml": ""}'::jsonb, '{"en": "St. Benedict Ashram, Hosur", "ml": ""}'::jsonb, '{"en": "<p>Land at Nagamangalam near Hosur, Tamil Nadu, was acquired in 2002 for farming, and a monastic community followed. In the following year a spring was discovered whose water is believed to bring healing through the intercession of Our Lady, and a church was built in honour of Our Lady of Lourdes. Many pilgrims come to pray here. The monks welcome pilgrims, celebrate Holy Mass and care for the farm, poultry and buffaloes.</p><p>Nagamangalam P.O., Krishnagiri, Tamil Nadu 635113</p>", "ml": ""}'::jsonb, 'assets/img/client/hosur-1.1378.jpg#w=800,1200,1378', null, '{}'::jsonb, 30, true);
insert into public.section_items (id, section_id, label, title, body, image_url, link, extra, sort, visible) values ('f2855b10-0d57-5fd4-a216-bd626b7f2744', '606f0ad1-1af2-592e-80e5-17da52a62b10', '{"en": "Minor seminary", "ml": ""}'::jsonb, '{"en": "Carlos Dayara, Kottayam", "ml": ""}'::jsonb, '{"en": "<p>The first home of the Vallombrosans in India, where candidates are welcomed and begin their formation. It is named after Mar Charles Lavigne, first Vicar Apostolic of Kottayam. Its chapel of St. Benedict draws many faithful for Mass and the novena to St. Benedict.</p><p>S.H. Mount P.O., Kottayam 686006</p>", "ml": ""}'::jsonb, 'assets/img/client/carlos-dayara.1080.jpg#w=800,1080', null, '{}'::jsonb, 40, true);
