insert into public.events (id, title, description, location, category, starts_on, ends_on, repeats_yearly, time_label, image_url, published) values ('45e6daee-64fd-5513-b407-ce5af54e5d0f', '{"en": "Anniversary of the Indian foundation", "ml": "ഭാരതത്തിലെ സ്ഥാപനത്തിന്റെ വാർഷികം"}'::jsonb, '{"en": "Anniversary of the decree of 25 November 1988 (Prot. No. 136/88) approving the Oriental branch.", "ml": "പൗരസ്ത്യ ശാഖയ്ക്ക് അംഗീകാരം നൽകിയ 1988 നവംബർ 25-ലെ ഡിക്രിയുടെ (പ്രോട്ട്. നമ്പർ 136/88) വാർഷികം."}'::jsonb, '{"en": "Mariamala Monastery", "ml": "മരിയമല ആശ്രമം"}'::jsonb, 'jubilee', '2026-11-25', null, true, null, null, true);
