insert into public.events (id, title, description, location, category, starts_on, ends_on, repeats_yearly, time_label, image_url, published) values ('3e06dd33-08c3-5cf7-bd84-a96292a7baf1', '{"en": "St. Benedict, Abbot", "ml": "വിശുദ്ധ ബെനഡിക്ട് ആബട്ട്"}'::jsonb, '{"en": "Feast of the father of Western monasticism, whose Rule the community follows.", "ml": "സമൂഹം പിന്തുടരുന്ന നിയമത്തിന്റെ രചയിതാവായ പാശ്ചാത്യ സന്യാസത്തിന്റെ പിതാവിന്റെ തിരുനാൾ."}'::jsonb, '{"en": "", "ml": ""}'::jsonb, 'feast', '2027-07-11', null, true, null, null, true);
insert into public.events (id, title, description, location, category, starts_on, ends_on, repeats_yearly, time_label, image_url, published) values ('fefd9d61-a718-5713-b814-0df8492f8977', '{"en": "St. John Gualbert, Founder", "ml": "വിശുദ്ധ ജോൺ ഗ്വാൽബെർട്ട്, സ്ഥാപകൻ"}'::jsonb, '{"en": "Solemnity of the founder of the Vallombrosan Congregation.", "ml": "വല്ലോംബ്രോസൻ സന്യാസസമൂഹത്തിന്റെ സ്ഥാപകന്റെ തിരുനാൾ."}'::jsonb, '{"en": "", "ml": ""}'::jsonb, 'feast', '2027-07-12', null, true, null, null, true);
