insert into public.posts (id, title, excerpt, body, cover_url, published_on, published, pinned) values ('fb045865-b33f-5929-8b65-38c4e6facc16', '{"en": "Welcome to our new website", "ml": "ഞങ്ങളുടെ പുതിയ വെബ്സൈറ്റിലേക്ക് സ്വാഗതം"}'::jsonb, '{"en": "News, feasts, the daily timetable and photographs of the community will be shared here in English and Malayalam.", "ml": "സമൂഹത്തിന്റെ വാർത്തകളും തിരുനാളുകളും അനുദിന സമയക്രമവും ചിത്രങ്ങളും ഇംഗ്ലീഷിലും മലയാളത്തിലും ഇവിടെ പങ്കുവയ്ക്കും."}'::jsonb, '{"en": "<p>This website brings together the story of the Vallombrosan Benedictines in Kerala, the monastic timetable, upcoming feasts, and news from Mariamala Monastery.</p><p>Content is being added in both English and Malayalam.</p>", "ml": "<p>കേരളത്തിലെ വല്ലോംബ്രോസൻ ബെനഡിക്ടൈൻസിന്റെ ചരിത്രം, സന്യാസ സമയക്രമം, വരാനിരിക്കുന്ന തിരുനാളുകൾ, മരിയമല ആശ്രമത്തിൽ നിന്നുള്ള വാർത്തകൾ എന്നിവ ഈ വെബ്സൈറ്റിൽ ലഭ്യമാണ്.</p><p>ഉള്ളടക്കം ഇംഗ്ലീഷിലും മലയാളത്തിലും ചേർത്തുകൊണ്ടിരിക്കുന്നു.</p>"}'::jsonb, 'assets/img/client/mariamala-front.1379.jpg#w=800,1200,1379', '2026-10-16', true, true);
insert into public.posts (id, title, excerpt, body, cover_url, published_on, published, pinned) values ('955c9955-1736-5028-bce5-df6a9b792dda', '{"en": "Mariamala, St. Mary’s Mount", "ml": "മരിയമല, സെന്റ് മേരീസ് മൗണ്ട്"}'::jsonb, '{"en": "The priory at Kaduthuruthy is the home of the congregation in India.", "ml": "കടുത്തുരുത്തി പഴുതുരുത്തിലെ ആശ്രമമാണ് കേരളത്തിലെ സമൂഹത്തിന്റെ ഭവനം."}'::jsonb, '{"en": "<p>St. Mary’s Monastery, Mariamala, was blessed on 29 June 2012 and became an independent priory in June 2016. It is the headquarters of the Vallombrosan Benedictine Congregation in India.</p>", "ml": "<p>കോട്ടയം ജില്ലയിലെ കടുത്തുരുത്തിക്കടുത്തുള്ള പഴുതുരുത്തിലാണ് മരിയമല ആശ്രമം (സെന്റ് മേരീസ് മൗണ്ട്). അർത്ഥികൾക്കായുള്ള മൈനർ സെമിനാരി കോട്ടയം എസ്.എച്ച്. മൗണ്ടിലും തത്ത്വശാസ്ത്ര-ദൈവശാസ്ത്ര പഠനഭവനം ബെംഗളൂരുവിലുമാണ്.</p>"}'::jsonb, null, '2026-10-16', true, false);
insert into public.posts (id, title, excerpt, body, cover_url, published_on, published, pinned) values ('7c7e7310-c91e-55d9-a705-61aad1dbe3ab', '{"en": "Vocation enquiries welcome", "ml": "ദൈവവിളി അന്വേഷണങ്ങൾ സ്വാഗതം"}'::jsonb, '{"en": "Young men discerning a call to monastic life can contact the community to visit and learn more.", "ml": "സന്യാസ ജീവിതത്തിലേക്കുള്ള വിളി വിവേചിക്കുന്ന യുവാക്കൾക്ക് സമൂഹത്തെ ബന്ധപ്പെട്ട് സന്ദർശിക്കാനും കൂടുതൽ അറിയാനും കഴിയും."}'::jsonb, '{"en": "<p>Formation moves from candidate and postulant to the novitiate, simple and solemn profession, and for some, priesthood. Please use the contact details on this website to arrange a visit.</p>", "ml": "<p>അർത്ഥി, പോസ്റ്റുലന്റ് എന്നീ ഘട്ടങ്ങളിൽ നിന്ന് നൊവിഷ്യേറ്റ്, താത്കാലിക-നിത്യ വ്രതങ്ങൾ, ചിലർക്ക് പൗരോഹിത്യം എന്നിങ്ങനെയാണ് പരിശീലനം. സന്ദർശനം ക്രമീകരിക്കാൻ ഈ വെബ്സൈറ്റിലെ ബന്ധപ്പെടാനുള്ള വിവരങ്ങൾ ഉപയോഗിക്കുക.</p>"}'::jsonb, null, '2026-10-15', true, false);
